/// What only Rust can perform for MultipartUpload: one required method per bespoke verb and per function its
/// expressions call, no default body, so a missing one is a build error that names it.
#[async_trait]
pub trait MultipartUploadActions: Send + Sync {
    /// The verb `calculate_chunk_size`, called by step `calculate_chunk_params`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn calculate_chunk_size(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;
}

